"""SHADOW VERIFIER -- partial stdlib cross-check, NOT the experiment.
Scope of validity: molecular formula, heavy-atom count, average MW from atomic weights.
Deliberately NOT attempted: HBD/HBA, TPSA, logP, rotatable bonds, ring perception
(those require substructure/aromaticity logic = the RDKit pipeline, out of scope here).
"""
import csv, collections, math, statistics, sys

AW = {'H':1.008,'B':10.81,'C':12.011,'N':14.007,'O':15.999,'F':18.998403162,
      'Si':28.085,'P':30.97376150,'S':32.06,'Cl':35.45,'Br':79.904,'I':126.90447}
HEAVY_EXCLUDE = {'H'}
ORGANIC = {'B','C','N','O','P','S','F','Cl','Br','I','Si'}
AROM = {'b','c','n','o','p','s','se','as'}
MAXVAL = {'C':4,'N':4,'O':2,'S':6,'P':5,'B':4,'Si':4,'F':1,'Cl':1,'Br':1,'I':1,'H':1}
BO = {'-':1,'=':2,'#':3,':':1.5}

def parse_formula(f):
    c, i, err = {}, 0, None
    while i < len(f):
        j = i+1
        while j < len(f) and f[j].islower(): j += 1        # element symbol (Cl, Br, Si)
        el = f[i:j]
        if el not in AW: err = f'unknown element {el!r} in formula'; break
        k = j
        while k < len(f) and f[k].isdigit(): k += 1
        n = int(f[i+ len(el) if False else j:k] or 1) if False else (int(f[j:k]) if k>j else 1)
        c[el] = c.get(el,0)+n; i = k
    if err: raise ValueError(err)
    return c

def mw_from_formula(f):
    return sum(AW[e]*n for e,n in parse_formula(f).items())

def heavy_from_formula(f):
    return sum(n for e,n in parse_formula(f).items() if e not in HEAVY_EXCLUDE)

def tokenize_smiles(s):
    """Minimal tokenizer + 2 structural checks. Raises SmilesError on invalid input."""
    class SmilesError(ValueError): pass
    if s is None or s.strip()=='': raise SmilesError('empty/blank SMILES')
    i, heavy, rings, val, order, prev, errors = 0, 0, collections.Counter(), None, 0, None, []
    while i < len(s):
        ch = s[i]
        if ch in '()': i += 1; continue
        if ch in '/\\@%+-.': i += 1; continue              # stereo/dir/charge-ish, ignored
        if ch in BO:
            o = BO[ch]
            if prev is not None: val[prev] = val.get(prev,0)+o
            order = o; i += 1; continue
        if ch == '[':
            j = s.index(']', i)
            body = s[i+1:j]; k = 0
            while k < len(body) and body[k].isdigit(): k += 1     # isotope
            el = ''
            while k < len(body) and (body[k].isalpha()): el += body[k]; k += 1
            if not el or el.capitalize() not in {e.capitalize() for e in ORGANIC|AROM}:
                raise SmilesError(f'unknown bracket element {el!r} in {s!r}')
            idx = heavy; heavy += 1; val[idx] = val.get(idx,0)
            prev = idx; i = j+1; continue
        if ch.isdigit() or ch == '%':
            r = s[i:i+2] if ch=='%' else ch
            step = 2 if ch=='%' else 1
            rings[r] += 1
            if prev is not None: val[prev] = val.get(prev,0)+ (order or 1)
            order = 0; i += step; continue
        if ch.isupper() or ch in AROM:
            two = s[i:i+2]
            el = two if two.capitalize() in {e.capitalize() for e in ORGANIC|AROM} and two[0].isupper() else ch
            known = {e.upper() for e in ORGANIC|AROM}
            if el.upper() not in known and not (ch.islower() and ch in AROM):
                raise SmilesError(f'unknown element token {el!r} in {s!r}')
            idx = heavy; heavy += 1
            v = val.get(idx,0) + (order if prev is not None else 0)
            val[idx] = v
            if prev is not None and order: val[prev] = val.get(prev,0)+order
            sym = (el.capitalize() if ch.isupper() else el.upper())
            maxv = MAXVAL.get(sym, 8)
            if v > maxv: errors.append(f'over-valent {sym}: {v}>{maxv}')
            prev, order, i = idx, 0, i+len(el)
            continue
        raise SmilesError(f'illegal SMILES character {ch!r} in {s!r}')
    for r,n in rings.items():
        if n % 2 != 0: raise SmilesError(f'unbalanced ring-closure label {r!r} (count {n}) in {s!r}')
    if errors: raise SmilesError('; '.join(errors))
    if heavy == 0: raise SmilesError(f'no atoms parsed from {s!r}')
    return heavy

rows = list(csv.DictReader(open('/workspace/design/MOLECULES.csv')))
res, neg = [], []
for r in rows:
    if r['stratum'] == 'negative':
        try:
            h = tokenize_smiles(r['smiles'])
            neg.append((r['id'],'ACCEPTED (CONTROL FAILED)',h))
        except Exception as e:
            neg.append((r['id'],f'rejected: {e}',''))
        continue
    f = r['formula']; hf = heavy_from_formula(f); mwt = mw_from_formula(f)
    try:
        hs = tokenize_smiles(r['smiles']); agree = 'OK' if hs == hf else f'MISMATCH smiles={hs} formula={hf}'
    except Exception as e:
        hs, agree = 'ERR', f'PARSE FAILED: {e}'
    res.append(dict(id=r['id'],name=r['name'],stratum=r['stratum'],risk=r['smiles_risk'],
                    formula=f,heavy_formula=hf,heavy_smiles=hs,agreement=agree,MW=round(mwt,3)))

mism = [x for x in res if x['agreement'] != 'OK']
print(f'analyzable molecules: {len(res)}   heavy-atom agreement: {len(res)-len(mism)}/{len(res)}')
print('formula<->SMILES cross-check failures:')
for x in mism: print('   ', x)
if not mism: print('    none')
print('\nnegative controls (must be rejected, never silently zero):')
for a,b,c in neg: print(f'   {a:5s} {b}')
print('\nMW gate table (avg MW from CIAAW-2021 abridged atomic weights):')
for x in res: print(f"   {x['id']:4s} {x['name'][:26]:27s} {x['formula']:12s} heavy={x['heavy_formula']:3d} MW={x['MW']:9.3f}")
mws = [x['MW'] for x in res]
print(f"\nMW summary: min={min(mws):.2f} max={max(mws):.2f} median={statistics.median(mws):.2f} mean={statistics.mean(mws):.2f} n={len(mws)}")
print(f"heavy atoms: min={min(x['heavy_formula'] for x in res)} max={max(x['heavy_formula'] for x in res)}")
print('STATUS: shadow verifier is a PARTIAL cross-check (formula/heavy/MW only); not the experiment.')
