capitalize() if ch.isupper() else el.upper())\n            maxv = MAXVAL.get(sym, 8)\n            if v > maxv: errors.append(f'over-valent {sym}: {v}>{maxv}')\n            prev, order, i = idx, 0, i+len(el)\n            continue\n        raise SmilesError(f'illegal SMILES character {ch!r} in {s!r}')\n    for r,n in rings.items():\n        if n % 2 != 0: raise SmilesError(f'unbalanced ring-closure label {r!r} (count {n}) in {s!r}')\n    if errors: raise SmilesError('; '.join(errors))\n    if heavy == 0: raise SmilesError(f'no atoms parsed from {s!r}')\n    return heavy\n\nrows = list(csv.DictReader(open('/workspace/design/MOLECULES.csv')))\nres, neg = [], []\nfor r in rows:\n    if r['stratum'] == 'negative':\n        try:\n            h = tokenize_smiles(r['smiles'])\n            neg.append((r['id'],'ACCEPTED (CONTROL FAILED)',h))\n        except Exception as e:\n            neg.append((r['id'],f'rejected: {e}',''))\n        continue\n    f = r['formula']; hf = heavy_from_formula(f); mwt = mw_from_formula(f)\n    try:\n        hs = tokenize_smiles(r['smiles']); agree = 'OK' if hs == hf else f'MISMATCH smiles={hs} formula={hf}'\n    except Exception as e:\n        hs, agree = 'ERR', f'PARSE FAILED: {e}'\n    res.append(dict(id=r['id'],name=r['name'],stratum=r['stratum'],risk=r['smiles_risk'],\n                    formula=f,heavy_formula=hf,heavy_smiles=hs,agreement=agree,MW=round(mwt,3)))\n\nmism = [x for x in res if x['agreement'] != 'OK']\nprint(f'analyzable molecules: {len(res)}   heavy-atom agreement: {len(res)-len(mism)}/{len(res)}')\nprint('formula<->SMILES cross-check failures:')\nfor x in mism: print('   ', x)\nif not mism: print('    none')\nprint('\\nnegative controls (must be rejected, never silently zero):')\nfor a,b,c in neg: print(f'   {a:5s} {b}')\nprint('\\nMW gate table (avg MW from CIAAW-2021 abridged atomic weights):')\nfor x in res: print(f\"   {x['id']:4s} {x['name'][:26]:27s} {x['formula']:12s} heavy={x['heavy_formula']:3d} MW={x['MW']:9.3f}\")\