BO = {'-':1,'=':2,'#':3,':':1.5}

class SmilesError(ValueError): pass

def parse_formula(f):
    c, i = {}, 0
    while i < len(f):
        j = i+1
        while j < len(f) and f[j].islower(): j += 1
        el = f[i:j]
        if el not in AW: raise ValueError(f'unknown element {el!r} in formula {f!r}')
        k = j
        while k < len(f) and f[k].isdigit(): k += 1
        c[el] = c.get(el,0) + (int(f[j:k]) if k>j else 1); i = k
    return c

mw_from_formula     = lambda f: sum(AW[e]*n for e,n in parse_formula(f).items())
heavy_from_formula  = lambda f: sum(n for e,n in parse_formula(f).items() if e!='H')

def count_heavy_smiles(s):
    """Minimal SMILES validity probe. Raises SmilesError with a SPECIFIC reason.
    Contract: never returns a value for input it cannot parse (no silent zeros)."""
    if s is None or not str(s).strip(): raise SmilesError('empty/blank SMILES')
    atoms, rings, pending, prev, i = [], collections.Counter(), 0, None, 0
    while i < len(s):
        ch = s[i]
        if ch in '()+.\\/@': i += 1; continue
        if ch in BO: pending = BO[ch]; i += 1; continue
        if ch == '[':
            j = s.index(']', i)
            if j < 0: raise SmilesError(f'unterminated bracket in {s!r}')
            body = s[i+1:j]
            m = re.match(r'(\d*)([A-Za-z]{1,2})', body)
            if not m: raise SmilesError(f'cannot read atom in bracket [{body}] of {s!r}')
            el = m.group(2)
            if len(el) == 2 and el[1].islower(): el = el[0]+el[1]
            else: el = el[0]
            if el not in AW: raise SmilesError(f'unknown bracket element {el!r} in {s!r}')
            atoms.append({'el':el,'val':pending,'bracket':True})
            if prev is not None: atoms[prev]['val'] += pending
            pending, prev, i = 0, len(atoms)-1, j+1
            continue
        if ch.isdigit() or ch == '%':
            r = s[i:i+2] if ch == '%' else ch
            step = 2 if ch == '%' else 1
            rings[r] += 1
            if prev is None: raise SmilesError(f'ring bond {r!r} with no preceding atom in {s!r}')
            atoms[prev]['val'] += (pending or 1); pending, i = 0, i+step
            continue
        two, one = s[i:i+2], ch
        if one.islower() and one in AROM_MAP: el, aromatic = AROM_MAP[one], True
        elif two in ORGANIC: el, aromatic = two, False
        elif one in ORGANIC: el, aromatic = one, False
        else: raise SmilesError(f'unknown element token {one!r} in {s!r}')
        atoms.append({'el':el,'val':pending,'bracket':aromatic})
        if prev is not None: atoms[prev]['val'] += pending
        pending, prev, i = 0, len(atoms)-1, i+(2 if not aromatic and two in ORGANIC and el==two else 1)
        continue
    for r,n in rings.items():
        if n % 2: raise SmilesError(f'unbalanced ring-closure label {r!r} (appears {n}x) in {s!r}')
    for a in atoms:
        if not a['bracket'] and a['el'] in MAXVAL and a['val'] > MAXVAL[a['el']]:
            raise SmilesError(f"over-valent {a['el']}: bond order sum {a['val']} > {MAXVAL[a['el']]} in {s!r}")
    if not atoms: raise SmilesError(f'no atoms parsed from {s!r}')
    return len(atoms)

rows = list(csv.DictReader(open('/workspace/design/MOLECULES.csv')))
res, neg = [], []
for r in rows:
    if r['stratum'] == 'negative':
        try: neg.append((r['id'], f'*** ACCEPTED -- CONTROL FAILED (got {count_heavy_smiles(r["smiles"])} atoms) ***'))
