ng\n        pending, prev, i = 0, len(atoms)-1, i+(2 if not aromatic and two in ORGANIC and el==two else 1)\n        continue\n    for r,n in rings.items():\n        if n % 2: raise SmilesError(f'unbalanced ring-closure label {r!r} (appears {n}x) in {s!r}')\n    for a in atoms:\n        if not a['bracket'] and a['el'] in MAXVAL and a['val'] > MAXVAL[a['el']]:\n            raise SmilesError(f\"over-valent {a['el']}: bond order sum {a['val']} > {MAXVAL[a['el']]} in {s!r}\")\n    if not atoms: raise SmilesError(f'no atoms parsed from {s!r}')\n    return len(atoms)\n\nrows = list(csv.DictReader(open('/workspace/design/MOLECULES.csv')))\nres, neg = [], []\nfor r in rows:\n    if r['stratum'] == 'negative':\n        try: neg.append((r['id'], f'*** ACCEPTED -- CONTROL FAILED (got {count_heavy_smiles(r[\"smiles\"])} atoms) ***'))\n        except SmilesError as e: neg.append((r['id'], f'rejected as required: {e}'))\n        except Exception as e: neg.append((r['id'], f'*** REJECTED BUT WRONG WAY: {type(e).__name__}: {e} ***'))\n        continue\n    f = r['formula']; hf = heavy_from_formula(f)\n    try:\n        hs = count_heavy_smiles(r['smiles']); ag = 'OK' if hs == hf else f'MISMATCH smiles={hs} vs formula={hf}'\n    except Exception as e: hs, ag = 'ERR', f'PARSE FAILED: {e}'\n    res.append(dict(r, heavy_formula=hf, heavy_smiles=hs, agree=ag, MW=round(mw_from_formula(f),3)))\n\nbad = [x for x in res if x['agree'] != 'OK']\nprint(f'analyzable molecules: {len(res)}  |  formula<->SMILES heavy-atom agreement: {len(res)-len(bad)}/{len(res)}')\nfor x in bad: print(f\"  FAIL {x['id']} {x['name']} smiles={x['smiles']!r} -> {x['agree']}\")\nif not bad: print('  all agree')\nprint('\\nNEGATIVE CONTROLS (contract: specific SmilesError, never a silent 0/blank row):')\nfor a,b in neg: print(f'  {a:5s} {b}')\nprint('\\nHARD-GATE MW TABLE (avg MW, CIAAW-2021 abridged atomic weights) -- EXPECTED values, hand-computable:')\nfor x in res: print(f\"  {x['id']:4s} {x['name'][:28]:29s} {x['formula']:11s} heavy={x['heavy_formula']:2d} MW={x['MW']:8.3f}  risk={x['smiles_risk']}\")\nmws=[x['MW'] for x in res]\nprint(f\"\\nMW: n={len(mws)} min={min(mws):.2f} max={max(mws):.2f} median={statistics.median(mws):.2f} mean={statistics.mean(mws):.2f} sd={statistics.stdev(mws):.2f}\")\nprint('NOTE: expected-value arithmetic only. No experiment executed.')\nPYEOF\npython3 /workspace/design/shadow_check.py 2>&1 | head -70", "exit_code": 0, "timed_out": false, "elapsed_seconds": 0.115, "output": "analyzable molecules: 47  |  formula<->SMILES heavy-atom agreement: 38/47\n  FAIL A05 ibuprofen smiles='CC(C)c1ccc(cc1)C(C)C(=O)O' -> MISMATCH smiles=14 vs formula=15\n  FAIL A15 omeprazole smiles='COc1ccc2[nH]c(nc2c1)S(=O)Cc1ncc(C)c(OC)c1C' -> PARSE FAILED: unknown bracket element 'n' in 'COc1ccc2[nH]c(nc2c1)S(=O)Cc1ncc(C)c(OC)c1C'\n  FAIL A18 theophylline smiles='Cn1cnc2c1c(=O)[nH]c(=O)n2C' -> PARSE FAILED: unknown bracket element 'n' in 'Cn1cnc2c1c(=O)[nH]c(=O)n2C'\n  FAIL A19 sulfanilamide smiles='Nc1ccc(cc1)S(=O)(=O)O' -> PARSE FAILED: over-valent O: bond order sum 4 > 2 in 'Nc1ccc(cc1)S(=O)(=O)O'\n  FAIL B06 cyclen smiles='C1CNCCNCCN1' -> MISMATCH smiles=9 vs formula=8\n  FAIL B17 choline cation smiles='C[n+](C)(C)CCO' -> PARSE FAILED: unknown bracket element 'n' in 'C[n+](C)(C)CCO'\n  FAIL B20 methyl hydrogen sulfate smiles='COS(=O)(=O)[O-]' -> PARSE FAILED: over-valent O: bond order sum 4 > 2 in 'COS(=O)(=O)[O-]'\n  FAIL B23 2-pyridone (tautomer b) smiles='O=c1ccc[nH]c1' -> PARSE FAILED: unknown bracket element 'n' in 'O=c1ccc[nH]c1'\n  FAIL B26 adenine smiles='Nc1ncnc2[nH]cnc12' -> PARSE FAILED: unknown bracket element 'n' in 'Nc1ncnc2[nH]cnc12'\n\nNEGATIVE CONTROLS (contract: specific SmilesError, never a silent 0/blank row):\n  NEG1  rejected as required: unknown element token 't' in 'not_a_smiles'\n  NEG2  rejected as required: empty/blank SMILES\n  NEG3  rejected as required: unbalanced ring-closure label '1' (appears 1x) in 'C1CC'\n  NEG4  rejected as required: