import csv, re, collections, statistics

AW = {'H':1.008,'B':10.81,'C':12.011,'N':14.007,'O':15.999,'F':18.998403162,
      'Si':28.085,'P':30.97376150,'S':32.06,'Cl':35.45,'Br':79.904,'I':126.90447}
TWO   = {'Cl','Br','Si'}
ONEUP = {'B','C','N','O','P','S','F','I'}
AROML = set('bcnops')
ALPHABET = set('()[]-=#:/\\@+%.0123456789') | ONEUP | AROML | {c for p in (TWO,) for c in p}
BRACKET   = re.compile(r'\[[^\]]*\]')
TWO_RE    = re.compile(r'(?![A-Z][a-z])', re.I)          # placeholder; census uses explicit walk
ATOM_AT   = re.compile(r'^([A-Z][a-z]?|[a-z])')
BR_EL     = re.compile(r'^(\d*)([A-Z][a-z]?)')

class ShadowError(ValueError): pass

def parse_formula(f):
    c, i = {}, 0
    while i < len(f):
        j = i+1
        while j < len(f) and f[j].islower(): j += 1
        el = f[i:j]
        if el not in AW: raise ShadowError(f'unknown element {el!r} in formula {f!r}')
        k = j
        while k < len(f) and f[k].isdigit(): k += 1
        c[el] = c.get(el,0) + (int(f[j:k]) if k>j else 1); i = k
    if not c: raise ShadowError(f'empty formula {f!r}')
    return c

