heavy_from_formula = lambda f: sum(n for e,n in parse_formula(f).items() if e!='H')

def smiles_census(s):
    """Count atoms in a SMILES string. NO valence/aromaticity judgement is made.
    Returns (heavy_count, list_of_unrecognised_chars)."""
    if s is None or not str(s).strip(): return 0, ['<empty>']
    s2, i, heavy, unknown = BRACKET.sub(lambda m: '\x00', s), 0, 0, []
    for tok in s2:
        if tok == '\x00':
            heavy += 1; continue
        if tok in '()-=#:/\\@+%.0123456789': continue
        if tok in ONEUP or tok in AROML: heavy += 1; continue
        if tok in ''.join(TWO):            continue          # handled by the walk below
