print(f'unbalanced ring labels among analyzable set: {len(odd)}' + ('' if not odd else f" -> {[x['id'] for x in odd]}"))
print('\nNEGATIVE CONTROLS (contract: must be caught by SOME layer, never silently zeroed):')
for a,b in neg: print(f'  {a:5s} {b}')
print('\nHARD-GATE MW TABLE  (avg MW from CIAAW-2021 abridged atomic weights) -- EXPECTED values, hand-auditable:')
for x in res:
