mws=[x['MW'] for x in res]
print(f"\nMW: n={len(mws)} min={min(mws):.2f} max={max(mws):.2f} median={statistics.median(mws):.2f} "
      f"mean={statistics.mean(mws):.2f} sd={statistics.stdev(mws):.2f}")
print('No experiment executed; these are design-stage expected values and cross-checks.')
