Run contract: exit 0 only if every control in DESIGN.md section 4 passes.
"""
import csv, hashlib, json, statistics, sys

try:
    from rdkit import Chem, RDLogger
    from rdkit.Chem import Descriptors, rdMolDescriptors
    from rdkit import __version__ as RDK_VERSION
except ImportError:
    sys.exit('RDKit required. This file is a specification in the design environment.')

RDLogger.DisableLog('rdApp.*')
TOL = {'B': 0.10, 'Si': 0.10}          # abridged-atomic-weight interval; 0.05 otherwise
DESCRIPTOR_CALLS = {
    'heavy_atoms':     lambda m: m.GetNumHeavyAtoms(),
    'MW_avg':          Descriptors.MolWt,
    'MW_mono':         Descriptors.ExactMolWt,
    'formula':         rdMolDescriptors.CalcMolFormula,
    'formal_charge':   Chem.GetFormalCharge,
    'n_charged_atoms': lambda m: sum(1 for a in m.GetAtoms() if a.GetFormalCharge()),
    'n_HBD':           rdMolDescriptors.CalcNumHBD,
    'n_HBA':           rdMolDescriptors.CalcNumHBA,
    'TPSA':            rdMolDescriptors.CalcTPSA,
    'n_rot':           rdMolDescriptors.CalcNumRotatableBonds,   # version-dependent
    'n_rings':         rdMolDescriptors.CalcNumRings,
    'n_arom_rings':    rdMolDescriptors.CalcNumAromaticRings,
    'n_heteroatoms':   rdMolDescriptors.CalcNumHeteroatoms,
    'frac_CSP3':       rdMolDescriptors.CalcFractionCSP3,
    'clogP':           Descriptors.MolLogP,
}

class ParseFailure(Exception):
    """Raised instead of emitting zeros -- see DESIGN.md 3, failure contract."""

def describe(smi, row_id):
    mol = Chem.MolFromSmiles(smi)
    if mol is None:                                   # NEVER return a zero row
        raise ParseFailure(f'{row_id}: RDKit could not parse {smi!r}')
    return {k: f(mol) for k, f in DESCRIPTOR_CALLS.items()}

def round_trip(smi, row_id):
    mol = Chem.MolFromSmiles(smi)
    can = Chem.MolToSmiles(mol)
    if describe(can, row_id) != describe(smi, row_id):
        raise AssertionError(f'K10 round-trip drift for {row_id}')
    return can

def lipinski(d):   # reported as a sum of parts, never four independent findings (A2)
    return {'MW>500': d['MW_avg'] > 500, 'clogP>5': d['clogP'] > 5,
            'HBD>5': d['n_HBD'] > 5, 'HBA>10': d['n_HBA'] > 10}

def spearman(x, y):
    def rank(v):
        o = sorted(range(len(v)), key=lambda i: v[i]); r = [0]*len(v)
        for pos, i in enumerate(o): r[i] = pos + 1
        return r
    a, b = rank(x), rank(y)
    ma, mb = statistics.mean(a), statistics.mean(b)
    num = sum((ai-ma)*(bi-mb) for ai, bi in zip(a, b))
    den = (sum((ai-ma)**2 for ai in a) * sum((bi-mb)**2 for bi in b)) ** 0.5
    return num/den if den else float('nan')

def main(path='MOLECULES.csv'):
    audit = {'rdkit_version': RDK_VERSION, 'input_sha256':
             hashlib.sha256(open(path,'rb').read()).hexdigest(), 'controls': {}}
    rows = list(csv.DictReader(open(path)))
    table, rejected = [], []
    for r in rows:
        try:
            d = describe(r['smiles'], r['id']); d['id'] = r['id']
            d['canonical_smiles'] = round_trip(r['smiles'], r['id'])
            table.append(d)
        except ParseFailure as e:
            rejected.append(str(e))
            if r['stratum'] != 'negative':
                raise SystemExit(f'K-fatal: analyzable molecule failed to parse: {e}')

    # K4: all 5 negative controls rejected, and no zero-row ever created
    audit['controls']['K4'] = (len(rejected) == 5 and
        all(x['id'] not in {r.split(':')[0] for r in []] for x in table))
    # K1: MW hard gate vs hand-audited formula arithmetic (see shadow_check.py table)
    k1 = []
    for r, d in [(r, next(t for t in table if t['id']==r['id'])) for r in rows
                 if r['stratum'] != 'negative']:
        tol = TOL.get('B' if 'B' in r['formula'] else 'X', 0.05)
        k1.append(abs(d['MW_avg'] - float(r['expected_MW'])) <= tol)
    audit['controls']['K1_MW_gate'] = {'n_pass': sum(k1), 'n': len(k1), 'pass': all(k1)}
    if not audit['controls']['K1_MW_gate']['pass']:
        sys.exit('K1 HARD GATE FAILED -- stop, downstream numbers are untrustworthy.')
    # K5 benzene zeros are real zeros; K6 charges; K7/K8 tautomer & enantiomer pairs
    by = {d['id']: d for d in table}
    audit['controls']['K5_benzene'] = dict(
        TPSA=by['B01']['TPSA'], n_HBD=by['B01']['n_HBD'], n_HBA=by['B01']['n_HBA'],
        pass_=by['B01']['TPSA']==0 and by['B01']['n_arom_rings']==1)
    audit['controls']['K6_charge'] = dict(
        choline=by['B17']['formal_charge'], acetate=by['B18']['formal_charge'],
        nitrobenzene_net=by['B21']['formal_charge'],
        nitrobenzene_charged_atoms=by['B21']['n_charged_atoms'])
    audit['controls']['K7_tautomers_differ'] = (by['B22']['n_HBD'], by['B23']['n_HBD']) != \
                                               (by['B22']['n_HBA'], by['B23']['n_HBA'])
    achiral = [k for k in DESCRIPTOR_CALLS if k != 'MW_mono']
    audit['controls']['K8_enantiomers_equal'] = all(
        by['B24'][k] == by['B25'][k] for k in achiral)
    # A2 redundancy: MW vs heavy atoms must be near-perfectly monotone (else join is broken)
    audit['A2_rho_MW_heavy'] = spearman([d['MW_avg'] for d in table],
                                        [d['heavy_atoms'] for d in table])
    mws = [d['MW_avg'] for d in table]
    audit['A1_MW_summary'] = dict(n=len(mws), min=min(mws), max=max(mws),
                                  median=statistics.median(mws), mean=statistics.mean(mws),
                                  sd=statistics.stdev(mws))
    json.dump(audit, open('audit.json','w'), indent=2, default=str)
    with open('descriptors.csv','w',newline='') as fh:
        w = csv.DictWriter(fh, fieldnames=list(table[0])); w.writeheader(); w.writerows(table)
    print('spec complete; see audit.json / descriptors.csv')
    # A3 note: Mann-Whitney U is computed for reproducibility only and is PRE-DECLARED
    # non-reportable as a finding at n~20/27. Report medians, IQRs, HL shift, rank-biserial,
    # and overlap fraction instead (DESIGN.md A3).

if __name__ == '__main__':
    main()
