", "thinking_blocks": [], "responses_reasoning_item": null, "action": {"command": "cd /workspace/design && cat > CONTROL_HARNESS_DRYRUN.py <<'PYEOF'
#!/usr/bin/env python3
"""CONTROL-HARNESS DRY RUN -- validates the LOGIC of controls K1-K10, stdlib only.

It injects a MOCK descriptor function that returns the design's EXPECTED values, so no
chemistry is exercised here. Purpose: prove each control is falsifiable -- i.e. that the
harness actually trips when its named failure mode is simulated. A control that cannot be
made to fail is not a control. NOT an experiment; no RDKit, no results.
"""
import csv, statistics, sys
sys.path.insert(0, '/workspace/design')

# mock descriptor table keyed by molecule id: the pre-declared expected descriptor vector
MOCK = {}
def build_mock(rows):
    for r in rows:
        if r['stratum'] == 'negative': continue
        MOCK[r['id']] = dict(
            heavy_atoms=int(r['heavy_ref']) if r.get('heavy_ref') else
                         sum(int(n or 1) for n in __import__('re').findall(r'[A-Z][a-z]?(\d*)', r['formula'])[0:] if False) or 0,
            MW_avg=float(r['expected_MW']), MW_mono=float(r['expected_MW']),
            formula=r['formula'], formal_charge=int(r['net_formal_charge'] or 0),
            n_charged_atoms=1 if r['net_formal_charge'] not in ('0','') else 0,
            n_HBD=int(float(r['expected_HBD'] or 0)), n_HBA=int(float(r['expected_HBA'] or 0)),
            TPSA=0.0 if r['id']=='B01' else 12.0*int(r['expected_HBA'] or 0),
            n_rot=int(float(r['expected_rot'] or 0)), n_rings=int(float(r['expected_rings'] or 0)),
            n_arom_rings=int(float(r['expected_arom_rings'] or 0)),
            n_heteroatoms=int(float(r['expected_HBA'] or 0)), frac_CSP3=0.3,
            clogP=float(r['expected_MW'])/100.0)
    # K6 detail: net-neutral but internally charged species
    for i in ('B16','B19','B21'): MOCK[i]['n_charged_atoms'] = 2
    # K5: benzene must have real, legitimate zeros
    MOCK['B01'].update(TPSA=0.0, n_HBD=0, n_HBA=0, n_rot=0, n_rings=1, n_arom_rings=1,
                       n_heteroatoms=0)
    # K7: tautomers must DIFFER; K8: enantiomers must be IDENTICAL
    MOCK['B22'].update(n_HBD=1, n_HBA=2); MOCK['B23'].update(n_HBD=2, n_HBA=1)
    MOCK['B25'] = dict(MOCK['B24'])

class ParseFailure(Exception): pass
BANNED = {'not_a_smiles','','C1CC','C(=O)(=O)(=O)O','q1ccccc1'}

def mock_describe(smi, rid, *, silent_zero=False, corrupt_mw=None):
    if smi in BANNED:
        if silent_zero:                       # simulated BAD pipeline: swallows the failure
            return {k: 0 for k in next(iter(MOCK.values()))}
        raise ParseFailure(f'{rid}: RDKit could not parse {smi!r}')
    d = dict(MOCK[rid])
    if corrupt_mw and rid == corrupt_mw[0]: d['MW_avg'] += corrupt_mw[1]
    return d

def mock_round_trip(smi, rid, *, drift=False):
    if drift and rid == 'A02': raise AssertionError('K10 round-trip drift for A02')
    return smi

def scenario(name, rows, **kw):
    import PIPELINE_SPEC as P
    desc = lambda s, r: mock_describe(s, r, **{k:v for k,v in kw.items() if k!='drift'})
    rtp  = lambda s, r: mock_round_trip(s, r, drift=kw.get('drift', False))
    try:
        a = P.evaluate_controls(rows, desc, rtp, 'MOCK')
        tripped = {k: v for k, v in a['controls'].items()
                   if (v.get('pass') is False if isinstance(v, dict) and 'pass' in v
                       else v is False)}
        print(f'  {name:38s} -> controls tripped: {sorted(tripped) or "NONE"}')
        return a
    except SystemExit as e:
        print(f'  {name:38s} -> HARD STOP raised: {e}')
        return 'STOPPED'
    except AssertionError as e:
        print(f'  {name:38s} -> assertion raised: {e}')
        return 'STOPPED'
    except ParseFailure as e:
        print(f'  {name:38s} -> parse failure escaped harness: {e}')
        return 'ESCAPED'

rows = list(csv.DictReader(open('MOLECULES.csv')))
# populate the heavy_ref column the mock needs, via the same arithmetic the gate uses
import re
AWH={'H':0}
for r in rows:
    if r['formula']:
        r['heavy_ref'] = sum(int(n or 1) for e,n in re.findall(r'([A-Z][a-z]?)(\d*)', r['formula']) if e and e!='H')
    else: r['heavy_ref']=''
build_mock(rows)

print('CONTROL-HARNESS DRY RUN (mock descriptor values = design EXPECTED values; harness logic only)\n')
print('A. happy path -- a correct pipeline must trip NOTHING:')
a = scenario('all-correct', rows)
if isinstance(a, dict):
    print('     K1:', a['controls']['K1_MW_gate']['pass'], '| K4:', a['controls']['K4'],
          '\n     K5 benzene:', a['controls']['K5_benzene'], '\n     K6 charges:', a['controls']['K6_charge'],
          '\n     K7 tautomers differ:', a['controls']['K7_tautomers_differ']['observed_differ'],
          '\n     K8 enantiomers equal:', a['controls']['K8_enantiomers_equal'],
          '\n     A2 rho(MW,heavy):', round(a['A2_rho_MW_heavy'],4), '\n     A1 MW summary:', a['A1_MW_summary'])

print('\nB. sabotage -- each named failure mode MUST trip its control:')
scenario('K1: MW off by +3 Da on A02', rows, corrupt_mw=('A02', 3.0))
scenario('K1: MW off by +0.02 (within tol)', rows, corrupt_mw=('A02', 0.02))
scenario('K4: parse errors swallowed -> zeros', rows, silent_zero=True)
scenario('K10: canonical round-trip drift', rows, drift=True)

print('\nC. negative controls fed to the CORRECT harness:')
for rid, smi in [('NEG1','not_a_smiles'),('NEG2',''),('NEG3','C1CC'),
                 ('NEG4','C(=O)(=O)(=O)O'),('NEG5','q1ccccc1')]:
    try:
        mock_describe(smi, rid); print(f'     {rid}: *** ACCEPTED -- harness would be broken ***')
    except ParseFailure as e: print(f'     {rid}: rejected -> {e}')
print('\nD. negative controls fed to the SABOTAGED harness (silent zeros):')
for rid, smi in [('NEG1','not_a_smiles'),('NEG4','C(=O)(=O)(=O)O')]:
    d = mock_describe(smi, rid, silent_zero=True)
    print(f"     {rid}: returned heavy_atoms={d['heavy_atoms']} TPSA={d['TPSA']} "
          f"-> invisible corruption; this is exactly what K4 exists to catch")
print('\nNOTE: mock values are pre-declared expectations. This exercises control LOGIC only.')
